class Solution:
    def distributeElements(self, nums: List[int]) -> List[List[int]]:
        a1 = [nums[0]]
        a2 = [nums[1]]
        for x in nums[2:]:
            if a1[-1] > a2[-1]:
                a1.append(x)
            else:
                a2.append(x)
        return [a1, a2]

distribute-money-to-maximum-children:
class Solution:
    def distMoney(self, money: int, children: int) -> int:
        if money < children:
            return -1
        money -= children
        count = min(children, money // 7)
        money -= count * 7
        children -= count
        if children > 0 and money == 3 and children == 1:
            count -= 1
        if children == 0 and money > 0:
            count -= 1
        return count

divide-a-string-into-groups-of-size-k:
class Solution:
    def divideString(self, s: str, k: int, fill: str) -> List[str]:
        while len(s) % k:
            s += fill
        return [s[i:i + k] for i in range(0, len(s), k)]

