fair-candy-swap:
class Solution:
    def fairCandySwap(self, aliceSizes: List[int], bobSizes: List[int]) -> List[int]:
        diff = (sum(bobSizes) - sum(aliceSizes)) // 2
        bset = set(bobSizes)
        for a in aliceSizes:
            if a + diff in bset:
                return [a, a + diff]
        return []

