final-array-state-after-k-multiplication:
class Solution:
    def getFinalState(self, nums: List[int], k: int, multiplier: int) -> List[int]:
        for _ in range(k):
            i = nums.index(min(nums))
            nums[i] *= multiplier
        return nums

final-prices-with-a-special-discount-in-:
class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        n = len(prices)
        res = []
        for i in range(n):
            d = 0
            for j in range(i + 1, n):
                if prices[j] <= prices[i]:
                    d = prices[j]
                    break
            res.append(prices[i] - d)
        return res

find-a-corresponding-node-of-a-binary-tr:
class Solution:
    def getTargetCopy(self, original: Optional[TreeNode], cloned: Optional[TreeNode], target: TreeNode) -> TreeNode:
        if not original:
            return None
        if original is target:
            return cloned
        return self.getTargetCopy(original.left, cloned.left, target) or self.getTargetCopy(original.right, cloned.right, target)

