find-common-characters:
class Solution:
    def commonChars(self, words: List[str]) -> List[str]:
        from collections import Counter
        c = Counter(words[0])
        for w in words[1:]:
            cw = Counter(w)
            for k in list(c):
                c[k] = min(c[k], cw[k])
        res = []
        for k, v in c.items():
            res.extend([k] * v)
        return res

