find-mode-in-binary-search-tree:
class Solution:
    def findMode(self, root: Optional[TreeNode]) -> List[int]:
        from collections import Counter
        c = Counter()
        def go(node):
            if not node:
                return
            c[node.val] += 1
            go(node.left)
            go(node.right)
        go(root)
        m = max(c.values())
        return [k for k, v in c.items() if v == m]

