class Solution:
    def sumZero(self, n: int) -> List[int]:
        res = []
        for i in range(1, n // 2 + 1):
            res.append(i)
            res.append(-i)
        if n % 2:
            res.append(0)
        return res

find-nearest-point-that-has-the-same-x-o:
class Solution:
    def nearestValidPoint(self, x: int, y: int, points: List[List[int]]) -> int:
        best = float('inf')
        ans = -1
        for i, (a, b) in enumerate(points):
            if a == x or b == y:
                d = abs(a - x) + abs(b - y)
                if d < best:
                    best = d
                    ans = i
        return ans

