find-resultant-array-after-removing-anag:
class Solution:
    def removeAnagrams(self, words: List[str]) -> List[str]:
        res = []
        prev = None
        for w in words:
            s = ''.join(sorted(w))
            if s != prev:
                res.append(w)
                prev = s
        return res
